// ============================================================
// VALIDER L'INSCRIPTION — bêta azy.education
// ============================================================
// Tout se vérifie ICI, côté serveur : la page peut être contournée, pas ce nœud.
// Aucun service extérieur n'est appelé (ni Formspree, ni reCAPTCHA de Google).

const entree = $input.first().json;
const body = entree && entree.body && typeof entree.body === 'object' ? entree.body : {};

const erreurs = [];
const texte = (v) => (typeof v === 'string' ? v.trim() : '');

// --- Pot de miel : champ invisible pour l'humain, rempli par un robot ---------
// Il ne s'agit pas d'un test d'intelligence : un robot remplit tous les champs
// qu'il trouve, un visiteur ne voit pas celui-ci. Aucune image à déchiffrer.
if (texte(body.site_web) !== '') {
  return [{ json: { valide: false, silencieux: true, motif: 'pot_de_miel' } }];
}

// --- Adresse électronique -----------------------------------------------------
// Volontairement permissif : le seul test qui prouve qu'une adresse existe est
// l'envoi du courriel de confirmation. On écarte les fautes de frappe grossières.
const email = texte(body.email).toLowerCase();
const FORME_EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
if (!email) erreurs.push('email requis');
else if (email.length > 254) erreurs.push('email trop long');
else if (!FORME_EMAIL.test(email)) erreurs.push('email invalide');

// --- Nom ----------------------------------------------------------------------
const nom = texte(body.nom);
if (!nom) erreurs.push('nom requis');
else if (nom.length > 120) erreurs.push('nom trop long');

// --- Profil : l'élève est refusé côté serveur --------------------------------
// C'est le parent qui inscrit l'enfant. Un visiteur qui modifie la page pour
// envoyer « eleve » se voit refuser ici, pas seulement dans le navigateur.
// Valeurs ANGLAISES : c'est le vocabulaire du CHECK en base (équipe api). Les libellés
// affichés restent en français dans la page — une seule langue traverse la chaîne,
// donc aucune table de traduction à maintenir entre le formulaire et la base.
const PROFILS = ['parent', 'teacher', 'institution'];
const profil = texte(body.profil).toLowerCase();
if (!profil) erreurs.push('profil requis');
else if (['eleve', 'élève', 'student'].includes(profil)) erreurs.push('profil_eleve_refuse');
else if (!PROFILS.includes(profil)) erreurs.push(`profil inconnu (${PROFILS.join(' | ')})`);

// --- Consentement : le texte EXACT accepté est conservé ----------------------
// Le RGPD demande de pouvoir prouver à quoi la personne a consenti, pas seulement
// qu'elle a coché. On enregistre donc la phrase affichée et l'horodatage.
const consentementDonne = body.consentement === true || body.consentement === 'true';
const consentementTexte = texte(body.consentement_texte);
if (!consentementDonne) erreurs.push('consentement requis');
if (!consentementTexte) erreurs.push('consentement_texte requis');
else if (consentementTexte.length > 2000) erreurs.push('consentement_texte trop long');

if (erreurs.length > 0) {
  return [{ json: { valide: false, silencieux: false, erreurs } }];
}

return [{
  json: {
    valide: true,
    email,
    nom,
    profil,
    consentement_texte: consentementTexte,
    // L'adresse IP sert uniquement à la preuve du consentement, pas au pistage.
    ip: texte(entree.headers && entree.headers['x-forwarded-for']).split(',')[0].trim() || null,
  },
}];

// Le lien porte le jeton EN CLAIR ; la base n'en a que l'empreinte. Un vol de la
// base ne permet donc pas de confirmer des inscriptions à la place des gens.
const v = $('Valider l\'inscription').first().json;
const jeton = $('Générer le jeton').first().json.jeton;
const base = $env.BETA_N8N_PUBLIC_URL || 'https://n8n.azy.education';
const lien = base + '/webhook/beta-confirmation?jeton=' + encodeURIComponent(jeton);
const echapper = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
return [{ json: { email: v.email, nom: v.nom,
  sujet: 'Confirmez votre inscription à la bêta d’Azy',
  html: `<p>Bonjour ${echapper(v.nom)},</p>
<p>Merci pour votre intérêt. Pour valider votre inscription, cliquez sur ce lien :</p>
<p><a href="${lien}">Confirmer mon inscription</a></p>
<p>Ce lien est valable <strong>7 jours</strong>. Passé ce délai, votre demande sera effacée.</p>
<p>Si vous n’êtes pas à l’origine de cette demande, ignorez ce message : sans confirmation, rien n’est conservé.</p>
<p>— L’équipe Azy</p>` } }];
